protected void run()
{
    
    next run();
    this.upadteFiscalCalendarYear();
    this.updatedueDateForCustTrans();
    this.updatedueDateForVendTrans();
    this.modifiedBy();
}

    private void upadteFiscalCalendarYear()
    {
        AccountingSourceExplorerTmp     accountingSourceExplorerTmp ;
        GeneralJournalEntry             generalJournalEntry;
        FiscalCalendarYear              fiscalCalendaryear;
        

        update_recordset accountingSourceExplorerTmp
            setting METName = fiscalCalendaryear.Name
            join JournalNumber,FiscalCalendarYear from generalJournalEntry
                where generalJournalEntry.JournalNumber == accountingSourceExplorerTmp.JournalNumber
            join RecId,Name from fiscalCalendaryear
                where fiscalCalendaryear.RecId == generalJournalEntry.FiscalCalendarYear;
    }

    private void updatedueDateForCustTrans()
    {
        AccountingSourceExplorerTmp     accountingSourceExplorerTmp;
        CustTrans                       custTrans;

        update_recordSet accountingSourceExplorerTmp
            setting METClosed = custTrans.Closed,
                    METDueDate = custTrans.DueDate,
                    METLastSettleVoucher = custTrans.LastSettleVoucher
            join Voucher, TransDate, Invoice, DocumentDate,Closed,DueDate,LastSettleVoucher from custTrans
                where custTrans.Voucher == accountingSourceExplorerTmp.SubledgerVoucher
                   && custTrans.TransDate == accountingSourceExplorerTmp.AccountingDate
                   && custTrans.Invoice != '';
    }

    private void updatedueDateForVendTrans()
    {
        AccountingSourceExplorerTmp     accountingSourceExplorerTmp;
        VendTrans                       vendTrans;

        update_recordSet accountingSourceExplorerTmp
            setting METClosed = vendTrans.Closed,
                    METDueDate = vendTrans.DueDate,
                    METLastSettleVoucher = vendTrans.LastSettleVoucher
            join Voucher, TransDate, Invoice, DocumentDate,Closed,DueDate,LastSettleVoucher from vendTrans
                where vendTrans.Voucher == accountingSourceExplorerTmp.SubledgerVoucher
                   && vendTrans.TransDate == accountingSourceExplorerTmp.AccountingDate
                   && vendTrans.Invoice != '';
    }

    private void modifiedBy()
    {
        AccountingSourceExplorerTmp         accountingSourceExplorerTmp;
        GeneralJournalEntry                 generalJournalEntry;
        SubledgerVoucherGeneralJournalEntry subledgerVoucherGeneralJournalEntry;
        SubledgerJournalEntry               subledgerJournalEntry;
        AccountingEvent                     accountingEvent;
        TransactionLog                      transactionLog;

        update_recordset accountingSourceExplorerTmp
            setting METModifiedBy = TransactionLog.CreatedBy
                join JournalNumber from generalJournalEntry
             where generalJournalEntry.JournalNumber == accountingSourceExplorerTmp.JournalNumber
                join GeneralJournalEntry from subledgerVoucherGeneralJournalEntry
            where subledgerVoucherGeneralJournalEntry.GeneralJournalEntry == generalJournalEntry.RecId
                join Voucher,VoucherDataAreaId,TransferId,CreatedTransactionId from subledgerJournalEntry
            where subledgerJournalEntry.Voucher == subledgerVoucherGeneralJournalEntry.Voucher &&
                  subledgerJournalEntry.VoucherDataAreaId == subledgerVoucherGeneralJournalEntry.VoucherDataAreaId &&
                  subledgerJournalEntry.TransferId == generalJournalEntry.TransferId
                join AccountingDate,RecId from accountingEvent
            where accountingEvent.AccountingDate == subledgerVoucherGeneralJournalEntry.AccountingDate &&
                  accountingEvent.RecId == subledgerJournalEntry.AccountingEvent
                join CreatedBy from TransactionLog 
            where transactionLog.CreatedTransactionId == subledgerJournalEntry.CreatedTransactionId;
            

    }
